export type CalendarCell = {
  date: string;
  total: number;
};

export type Entry = {
  id: string;
  merchant: string;
  amount: number;
};

export type Today = {
  total: number;
  entries: Entry[];
};

export type TodayView = {
  totalLabel: string;
  rows: Entry[];
};

package domain

// Charge はカード明細 1 行。
type Charge struct {
	Merchant string
	Amount   int64
}

// ToTransaction は Charge を Transaction に変換する。
func (c Charge) ToTransaction(id string) Transaction {
	return Transaction{ID: id, Merchant: c.Merchant, Amount: c.Amount}
}

Transaction:
  type: object
  required: [id, merchant, amount, occurredAt]
  properties:
    id: { type: string }
    merchant: { type: string }
    amount: { type: integer, format: int64 }
    occurredAt: { type: string, format: date-time }

PushSubscription:
  type: object
  required: [endpoint, p256dh, auth]
  properties:
    endpoint: { type: string }
    p256dh: { type: string }
    auth: { type: string }

