import { TodayIsland } from '@/components/today-island';

export default function HomePage() {
  return (
    <main>
      <h1>支出トラッカー</h1>
      <TodayIsland />
    </main>
  );
}

import { PushToggle } from '@/components/push-toggle';

export default function PushPage() {
  return (
    <main>
      <h1>通知設定</h1>
      <PushToggle />
    </main>
  );
}

export function CalendarGrid({ cells }: { cells: CalendarCell[] }) {
  return (
    <div data-component="CalendarGrid">
      {cells.map((c) => (
        <span key={c.date}>
          {c.date}: {c.total}
        </span>
      ))}
    </div>
  );
}

export function CalendarIsland({ month }: { month: string }) {
  const [cells, setCells] = useState<CalendarCell[]>([]);

  useEffect(() => {
    getDays(month).then((d) => setCells(toCells(d)));
  }, [month]);

  return (
    <div data-component="CalendarIsland">
      <CalendarGrid cells={cells} />
    </div>
  );
}

export function EntryList({ entries }: { entries: Entry[] }) {
  return (
    <ul data-component="EntryList">
      {entries.map((e) => (
        <li key={e.id}>
          {e.merchant} {e.amount}
        </li>
      ))}
    </ul>
  );
}

export function PushToggle() {
  const subscribe = async () => {
    await fetch(`${API_DOMAIN}/push/subscriptions`, { method: 'POST' });
  };

  return (
    <button data-component="PushToggle" onClick={subscribe}>
      通知を有効にする
    </button>
  );
}

export function TodayIsland() {
  const [view, setView] = useState<TodayView | null>(null);

  useEffect(() => {
    getToday().then((t) => setView(toTodayView(t)));
  }, []);

  if (!view) return <p data-component="TodayIsland">読み込み中</p>;
  return (
    <div data-component="TodayIsland">
      <TotalCard view={view} />
      <EntryList entries={view.rows} />
    </div>
  );
}

export function TotalCard({ view }: { view: TodayView }) {
  return (
    <section data-component="TotalCard">
      <h2>今日の合計</h2>
      <p>{view.totalLabel}</p>
    </section>
  );
}

export async function fetcher<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${API_DOMAIN}${url}`, init);
  if (!res.ok) {
    throw new Error(`request failed: ${res.status}`);
  }
  return (await res.json()) as T;
}

CREATE TABLE transactions (
  id          TEXT PRIMARY KEY,
  merchant    TEXT NOT NULL,
  amount      BIGINT NOT NULL,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS inboxes (
  id         TEXT PRIMARY KEY,
  history_id TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE push_subscriptions (
  endpoint TEXT PRIMARY KEY,
  p256dh   TEXT NOT NULL,
  auth     TEXT NOT NULL
);

export function getDays(month: string): Promise<DailyTotals> {
  return fetcher<DailyTotals>(`/days?month=${month}`);
}

export function toCells(days: DailyTotals): CalendarCell[] {
  return Object.entries(days).map(([date, total]) => ({ date, total }));
}

export function getToday(): Promise<Today> {
  return fetcher<Today>('/today');
}

export function getEntries(): Promise<Entry[]> {
  return fetcher<Entry[]>('/entries');
}

export function createTransaction(body: Entry): Promise<void> {
  return fetcher<void>('/transactions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function toTodayView(today: Today): TodayView {
  return {
    totalLabel: `${today.total.toLocaleString()}円`,
    rows: today.entries,
  };
}

