func (s *Server) handleDays(w http.ResponseWriter, r *http.Request) {
	days, err := s.store.DailyTotals(r.Context(), r.URL.Query().Get("month"))
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	_ = json.NewEncoder(w).Encode(days)
}

func (s *Server) handleEntries(w http.ResponseWriter, r *http.Request) {
	txs, err := s.store.ListRecent(r.Context(), 50)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	_ = json.NewEncoder(w).Encode(txs)
}

func (s *Server) handleSubscribe(w http.ResponseWriter, r *http.Request) {
	var sub push.Subscription
	if err := json.NewDecoder(r.Body).Decode(&sub); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if err := s.store.SaveSubscription(r.Context(), sub); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusCreated)
}

func (s *Server) handleUnsubscribe(w http.ResponseWriter, r *http.Request) {
	var sub push.Subscription
	if err := json.NewDecoder(r.Body).Decode(&sub); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if err := s.store.RemoveSubscription(r.Context(), sub.Endpoint); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func NewServer(st *store.Store, v *auth.Verifier) *Server {
	return &Server{store: st, verifier: v}
}

func (s *Server) handleToday(w http.ResponseWriter, r *http.Request) {
	txs, err := s.store.ListByDate(r.Context(), time.Now())
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	total := domain.Sum(txs)
	resp := map[string]any{"total": total, "entries": txs}
	_ = json.NewEncoder(w).Encode(resp)
}

func (s *Server) handleCreateTransaction(w http.ResponseWriter, r *http.Request) {
	var tx domain.Transaction
	if err := json.NewDecoder(r.Body).Decode(&tx); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if err := s.store.InsertTransaction(r.Context(), tx); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusCreated)
}

func (s *Server) handleDeleteTransaction(w http.ResponseWriter, r *http.Request) {
	if err := s.store.DeleteTransaction(r.Context(), r.PathValue("id")); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (v *Verifier) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") == "" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func (c Charge) ToTransaction(id string) Transaction {
	return Transaction{ID: id, Merchant: c.Merchant, Amount: c.Amount}
}

func Sum(txs []Transaction) int64 {
	var total int64
	for _, t := range txs {
		total += t.Amount
	}
	return total
}

func NewHandler(p *parser.Parser, s *store.Store) *Handler {
	return &Handler{parser: p, store: s}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	charge, ok := h.parser.Parse("unknown", r.FormValue("body"))
	if !ok {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	if err := h.store.InsertTransaction(r.Context(), charge.ToTransaction("gmail")); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusAccepted)
}

func (p *Parser) Parse(merchant, body string) (domain.Charge, bool) {
	m := amountRe.FindStringSubmatch(body)
	if m == nil {
		return domain.Charge{}, false
	}
	n, err := strconv.ParseInt(m[1], 10, 64)
	if err != nil {
		return domain.Charge{}, false
	}
	return domain.Charge{Merchant: merchant, Amount: n}, true
}

